import { createChart } from '../../core/utHelper';
import { EChartsType } from '../../../../src/echarts';

function getLargeBarEls(chart: EChartsType) {
    const els: any[] = [];
    (chart as any).getZr().storage.traverse(function (el: any) {
        if (el.type === 'largeBar') {
            els.push(el);
        }
    });
    return els;
}

describe('bar_large', function () {
    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart({ width: 400, height: 300 });
    });

    afterEach(function () {
        chart.dispose();
    });

    function makeData(count: number) {
        const data = [];
        for (let i = 0; i < count; i++) {
            data.push([i, (i % 50) + 1]);
        }
        return data;
    }

    it('borderColor should not hide the bar color', function () {
        chart.setOption({
            xAxis: {},
            yAxis: {},
            series: [{
                type: 'bar',
                large: true,
                itemStyle: {
                    color: '#f00',
                    borderColor: '#000'
                },
                data: makeData(3000)
            }]
        });

        const els = getLargeBarEls(chart);
        expect(els.length).toBe(1);
        const el = els[0];
        expect(el.style.fill).toBe('#f00');
        expect(el.style.stroke).toBe('#000');
        // The bar is thinner than the default 1px border, so the border must be
        // narrowed, otherwise it covers the whole bar.
        expect(el.style.lineWidth).toBeLessThan(el.barWidth);
    });

    it('keeps the configured border width when bars are wide enough', function () {
        chart.setOption({
            xAxis: {},
            yAxis: {},
            series: [{
                type: 'bar',
                large: true,
                largeThreshold: 1,
                barWidth: 40,
                itemStyle: {
                    color: '#f00',
                    borderColor: '#000',
                    borderWidth: 2
                },
                data: makeData(5)
            }]
        });

        const els = getLargeBarEls(chart);
        expect(els.length).toBe(1);
        expect(els[0].style.lineWidth).toBe(2);
    });
});

