import { createChart } from '../../core/utHelper';
import { EChartsType } from '../../../../src/echarts';

describe('legend_action_isolation', function () {
    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart();
    });

    afterEach(function () {
        chart.dispose();
    });

    function makeOption() {
        return {
            legend: [{
                id: 'legendA',
                data: ['a1', 'a2']
            }, {
                id: 'legendB',
                data: ['b1', 'b2']
            }],
            xAxis: { type: 'category', data: ['x'] },
            yAxis: {},
            series: [
                { id: 'a1', name: 'a1', type: 'bar', data: [1] },
                { id: 'a2', name: 'a2', type: 'bar', data: [2] },
                { id: 'b1', name: 'b1', type: 'bar', data: [3] },
                { id: 'b2', name: 'b2', type: 'bar', data: [4] }
            ]
        };
    }

    function getLegendModel(id: string) {
        return (chart as any).getModel().queryComponents({
            mainType: 'legend',
            id
        })[0];
    }

    it('legendUnSelect targeted by legendId only affects that legend', function () {
        chart.setOption(makeOption());

        chart.dispatchAction({
            type: 'legendUnSelect',
            legendId: 'legendA',
            name: 'a1'
        });

        expect(getLegendModel('legendA').isSelected('a1')).toBe(false);
        expect(getLegendModel('legendB').isSelected('b1')).toBe(true);
    });

    it('legendAllSelect targeted by legendId does not restore other legends', function () {
        chart.setOption(makeOption());

        chart.dispatchAction({
            type: 'legendUnSelect',
            legendId: 'legendB',
            name: 'b1'
        });
        expect(getLegendModel('legendB').isSelected('b1')).toBe(false);

        chart.dispatchAction({
            type: 'legendAllSelect',
            legendId: 'legendA'
        });

        // legendB should keep its own unselected state.
        expect(getLegendModel('legendB').isSelected('b1')).toBe(false);
        expect(getLegendModel('legendA').isSelected('a1')).toBe(true);
    });

    it('actions without a legend query still apply to every legend', function () {
        chart.setOption(makeOption());

        chart.dispatchAction({
            type: 'legendInverseSelect'
        });

        expect(getLegendModel('legendA').isSelected('a1')).toBe(false);
        expect(getLegendModel('legendB').isSelected('b1')).toBe(false);
    });
});

