import { createChart } from '../../core/utHelper';
import { EChartsType } from '../../../../src/echarts';

describe('marker_formatter', function () {
    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart();
    });

    afterEach(function () {
        chart.dispose();
    });

    function makeOption(markerType: 'markPoint' | 'markLine' | 'markArea', params: any[]) {
        const marker: any = {
            label: {
                formatter(param: any) {
                    params.push(param);
                    return 'ok';
                }
            }
        };
        marker.data = markerType === 'markArea'
            ? [[{ xAxis: 'A' }, { xAxis: 'B' }]]
            : [{ type: 'max' }];

        const series: any = {
            id: 'sid',
            name: 'sname',
            type: 'line',
            data: [10, 20, 30]
        };
        series[markerType] = marker;

        return {
            xAxis: { type: 'category', data: ['A', 'B', 'C'] },
            yAxis: {},
            series: [series]
        };
    }

    it('markPoint label formatter receives series information', function () {
        const params: any[] = [];
        chart.setOption(makeOption('markPoint', params));
        expect(params.length).toBeGreaterThan(0);
        expect(params[0].seriesId).toBe('sid');
        expect(params[0].seriesName).toBe('sname');
        expect(params[0].seriesType).toBe('line');
        expect(params[0].seriesIndex).toBe(0);
    });

    it('markLine label formatter receives series information', function () {
        const params: any[] = [];
        chart.setOption(makeOption('markLine', params));
        expect(params.length).toBeGreaterThan(0);
        expect(params[0].seriesId).toBe('sid');
        expect(params[0].seriesName).toBe('sname');
        expect(params[0].seriesType).toBe('line');
        expect(params[0].seriesIndex).toBe(0);
    });

    it('markArea label formatter receives series information', function () {
        const params: any[] = [];
        chart.setOption(makeOption('markArea', params));
        expect(params.length).toBeGreaterThan(0);
        expect(params[0].seriesId).toBe('sid');
        expect(params[0].seriesName).toBe('sname');
        expect(params[0].seriesType).toBe('line');
        expect(params[0].seriesIndex).toBe(0);
    });
});

