import { createChart } from '../../core/utHelper';
import { EChartsType } from '../../../../src/echarts';

function findPolygon(chart: EChartsType) {
    let found: any = null;
    (chart as any).getZr().storage.traverse(function (el: any) {
        if (el.type === 'ec-polygon') {
            found = el;
        }
    });
    return found;
}

describe('line_step_area_nulls', function () {
    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart({ width: 400, height: 300 });
    });

    afterEach(function () {
        chart.dispose();
    });

    function makeOption(step: string, connectNulls: boolean) {
        return {
            xAxis: { type: 'category', data: ['a', 'b', 'c', 'd', 'e'] },
            yAxis: {},
            series: [{
                type: 'line',
                step,
                connectNulls,
                areaStyle: {},
                data: [10, null, 30, null, 50]
            }]
        };
    }

    ['start', 'middle', 'end'].forEach(function (step) {
        it(`step: ${step} + connectNulls keeps the area base aligned`, function () {
            chart.setOption(makeOption(step, true));
            const polygon = findPolygon(chart);
            expect(polygon).toBeTruthy();
            const points = polygon.shape.points;
            const stackedOnPoints = polygon.shape.stackedOnPoints;
            expect(stackedOnPoints.length).toBe(points.length);
            // The base of the area must share the x coordinate of each point,
            // otherwise the filled polygon is skewed.
            for (let i = 0; i < points.length; i += 2) {
                expect(stackedOnPoints[i]).toBeCloseTo(points[i], 4);
            }
        });

        it(`step: ${step} without connectNulls keeps the area base aligned`, function () {
            chart.setOption(makeOption(step, false));
            const polygon = findPolygon(chart);
            expect(polygon).toBeTruthy();
            const points = polygon.shape.points;
            const stackedOnPoints = polygon.shape.stackedOnPoints;
            expect(stackedOnPoints.length).toBe(points.length);
            for (let i = 0; i < points.length; i += 2) {
                if (!isNaN(points[i])) {
                    expect(stackedOnPoints[i]).toBeCloseTo(points[i], 4);
                }
            }
        });
    });

    it('connectNulls: false keeps the null gaps in the stepped path', function () {
        chart.setOption(makeOption('end', false));
        const polygon = findPolygon(chart);
        const points = polygon.shape.points;
        let nullCount = 0;
        for (let i = 0; i < points.length; i += 2) {
            if (isNaN(points[i]) || isNaN(points[i + 1])) {
                nullCount++;
            }
        }
        expect(nullCount).toBeGreaterThan(0);
    });

    it('connectNulls: true removes the null gaps in the stepped path', function () {
        chart.setOption(makeOption('end', true));
        const polygon = findPolygon(chart);
        const points = polygon.shape.points;
        for (let i = 0; i < points.length; i += 2) {
            expect(isNaN(points[i]) || isNaN(points[i + 1])).toBe(false);
        }
    });
});

