function createPolarClipPath(
    polar: Polar,
    hasAnimation: boolean,
    seriesModel: SeriesModelWithLineWidth,
    // When the series opts out of clipping (`clip: false`) the clip path is only
    // used to play the reveal animation, so it has to cover everything instead
    // of cutting the content off at the bounds of the coordinate system.
    expandToFullArea?: boolean
) {
    const sectorArea = polar.getArea();
    // Avoid float number rounding error for symbol on the edge of axis extent.

    let r0 = round(sectorArea.r0, 1);
    let r = round(sectorArea.r, 1);
    let startAngle = sectorArea.startAngle;
    let endAngle = sectorArea.endAngle;
    let clockwise = sectorArea.clockwise;
    if (expandToFullArea) {
        r0 = 0;
        // The content may exceed the radius extent by any amount, so make the
        // clip area large enough to never cut it off.
        r += Math.max(r, 1) * 2;
        startAngle = 0;
        endAngle = Math.PI * 2;
        clockwise = true;
    }
    const clipPath = new graphic.Sector({
        shape: {
            cx: round(polar.cx, 1),
            cy: round(polar.cy, 1),
            r0: r0,
            r: r,
            startAngle: startAngle,
            endAngle: endAngle,
            clockwise: clockwise
        }
    });

    if (hasAnimation) {
        const isRadial = polar.getBaseAxis().dim === 'angle';

        if (isRadial) {
            clipPath.shape.endAngle = startAngle;
        }
        else {
            clipPath.shape.r = r0;
        }

        graphic.initProps(clipPath, {
            shape: {
                endAngle: endAngle,
                r: r
            }
        }, seriesModel);
    }
    return clipPath;
}

