import { createChart } from '../../core/utHelper';
import { EChartsType } from '../../../../src/echarts';

function getLineGroupClipShape(chart: EChartsType) {
    let shape: any = null;
    (chart as any).getZr().storage.traverse(function (el: any) {
        if (el.type === 'ec-polyline' && el.parent && el.parent.getClipPath()) {
            shape = el.parent.getClipPath().shape;
        }
    });
    return shape;
}

