import { createChart } from '../../core/utHelper';
import { EChartsType } from '../../../../src/echarts';

describe('bar_bandWidth_inversed_time_axis', function () {
    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart({ width: 500, height: 300 });
    });

    afterEach(function () {
        chart.dispose();
    });

    function layoutOf(inverse: boolean) {
        chart.setOption({
            animation: false,
            xAxis: { type: 'time', inverse },
            yAxis: {},
            series: [{
                type: 'bar',
                data: [
                    ['2020-01-01', 10],
                    ['2020-01-02', 20],
                    ['2020-01-03', 30]
                ]
            }]
        }, true);
        const data = (chart as any).getModel().getSeriesByIndex(0).getData();
        return {
            size: data.getLayout('size') as number,
            centers: [0, 1, 2].map(function (i) {
                const layout = data.getItemLayout(i);
                return layout.x + layout.width / 2;
            })
        };
    }

    it('bandWidth is the same as on a normal time axis', function () {
        const normal = layoutOf(false);
        const inversed = layoutOf(true);
        expect(inversed.size).toBeCloseTo(normal.size, 6);
    });

    it('bars stay inside the grid on an inversed time axis', function () {
        const inversed = layoutOf(true);
        const gridRect = (chart as any).getModel().getComponent('grid')
            .coordinateSystem.getRect();
        inversed.centers.forEach(function (center) {
            expect(center).toBeGreaterThanOrEqual(gridRect.x - 1);
            expect(center).toBeLessThanOrEqual(gridRect.x + gridRect.width + 1);
        });
    });

    it('bars are mirrored compared to a normal time axis', function () {
        const normal = layoutOf(false);
        const inversed = layoutOf(true);
        for (let i = 0; i < 3; i++) {
            expect(inversed.centers[i]).toBeCloseTo(normal.centers[2 - i], 6);
        }
    });
});

