import { createChart } from '../../core/utHelper';
import { EChartsType } from '../../../../src/echarts';

describe('scratch_ticks', function () {
    let chart: EChartsType;
    beforeEach(function () { chart = createChart({width: 500, height: 300}); });
    afterEach(function () { chart.dispose(); });

    function report(name: string, option: any) {
        chart.setOption(option, true);
        const model = (chart as any).getModel();
        ['xAxis', 'yAxis'].forEach(function (which) {
            const axisModel = model.getComponent(which);
            if (!axisModel) { return; }
            const axis = axisModel.axis;
            const extent = axis.getExtent();
            const lo = Math.min(extent[0], extent[1]) - 1e-6;
            const hi = Math.max(extent[0], extent[1]) + 1e-6;
            const ticks = axis.getTicksCoords();
            const minor = axis.getMinorTicksCoords();
            const out = ticks.filter((t: any) => t.coord < lo || t.coord > hi);
            const minorOut: any[] = [];
            minor.forEach((g: any[]) => g.forEach((t: any) => {
                if (t.coord < lo || t.coord > hi) { minorOut.push(t.coord); }
            }));
            if (out.length || minorOut.length) {
                console.log('OVERFLOW', name, which, 'extent', JSON.stringify(extent),
                    'OUT', JSON.stringify(out), 'MINOROUT', JSON.stringify(minorOut));
            }
        });
    }

    it('all', function () {
        const filterModes = ['filter', 'none', 'empty', 'weakFilter'];
        const types = ['category', 'value', 'time', 'log'];
        types.forEach(function (type) {
            filterModes.forEach(function (fm) {
                const data: any[] = [];
                for (let i = 0; i < 12; i++) {
                    if (type === 'category') { data.push(i + 1); }
                    else if (type === 'time') { data.push(['2020-01-' + (i + 1), i + 1]); }
                    else if (type === 'log') { data.push([Math.pow(2, i), i + 1]); }
                    else { data.push([i * 1.7 + 1, i + 1]); }
                }
                const xAxis: any = { type, minorTick: { show: true }, minorSplitLine: {show: true} };
                if (type === 'category') {
                    xAxis.data = ['a','b','c','d','e','f','g','h','i','j','k','l'];
                }
                [[12, 63], [0, 100], [33.3, 71.9], [5, 17]].forEach(function (range) {
                    report(type + '/' + fm + '/' + range.join('-'), {
                        animation: false,
                        xAxis,
                        yAxis: { minorTick: {show: true} },
                        dataZoom: [
                            { type: 'inside', start: range[0], end: range[1], filterMode: fm },
                            { type: 'inside', yAxisIndex: 0, start: range[0], end: range[1], filterMode: fm }
                        ],
                        series: [{ type: 'line', data }]
                    });
                });
            });
        });
    });
});
