// Tolerance to avoid treating a rounding error as an overflow.
const TICK_COORD_EXTENT_EPSILON = 1e-8;

function isTickCoordOutOfExtent(coord: number, extentMin: number, extentMax: number): boolean {
    return coord < extentMin - TICK_COORD_EXTENT_EPSILON
        || coord > extentMax + TICK_COORD_EXTENT_EPSILON;
}

// The scale extent does not necessarily end on a tick, for example when
// `dataZoom` narrows the visible window. Together with the rounding of some
// scales (e.g. log) that may place a tick slightly, or even clearly, out of the
// axis extent, where it is drawn outside of the grid area and makes the chart
// look broken. Keep every tick inside the extent instead.
function clampTicksCoords(axis: Axis, ticksCoords: TickCoord[]): void {
    const axisExtent = axis.getExtent();
    const extentMin = Math.min(axisExtent[0], axisExtent[1]);
    const extentMax = Math.max(axisExtent[0], axisExtent[1]);
    for (let i = 0; i < ticksCoords.length; i++) {
        const coord = ticksCoords[i].coord;
        if (coord < extentMin) {
            ticksCoords[i].coord = extentMin;
        }
        else if (coord > extentMax) {
            ticksCoords[i].coord = extentMax;
        }
    }
}

