import { createChart } from '../../core/utHelper';
import { EChartsType } from '../../../../src/echarts';

describe('axis_ticks_grid_overflow', function () {
    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart({ width: 500, height: 300 });
    });

    afterEach(function () {
        chart.dispose();
    });

    function getXAxis() {
        return (chart as any).getModel().getComponent('xAxis').axis;
    }

    function collectOutOfExtent(axis: any) {
        const extent = axis.getExtent();
        const min = Math.min(extent[0], extent[1]);
        const max = Math.max(extent[0], extent[1]);
        const out: number[] = [];
        axis.getTicksCoords().forEach(function (tick: any) {
            if (tick.coord < min - 1e-6 || tick.coord > max + 1e-6) {
                out.push(tick.coord);
            }
        });
        axis.getMinorTicksCoords().forEach(function (group: any[]) {
            group.forEach(function (tick: any) {
                if (tick.coord < min - 1e-6 || tick.coord > max + 1e-6) {
                    out.push(tick.coord);
                }
            });
        });
        return out;
    }

    it('log axis ticks stay in the grid when zoomed', function () {
        const data: number[][] = [];
        for (let i = 0; i < 12; i++) {
            data.push([Math.pow(2, i), i + 1]);
        }
        chart.setOption({
            animation: false,
            xAxis: { type: 'log', minorTick: { show: true } },
            yAxis: {},
            dataZoom: [{ type: 'inside', start: 33.3, end: 71.9, filterMode: 'none' }],
            series: [{ type: 'line', data }]
        });
        expect(collectOutOfExtent(getXAxis())).toEqual([]);
    });

    it('value axis ticks stay in the grid when zoomed', function () {
        const data: number[][] = [];
        for (let i = 0; i < 12; i++) {
            data.push([i * 1.7 + 1, i + 1]);
        }
        chart.setOption({
            animation: false,
            xAxis: { type: 'value', minorTick: { show: true } },
            yAxis: {},
            dataZoom: [{ type: 'inside', start: 12, end: 63 }],
            series: [{ type: 'line', data }]
        });
        expect(collectOutOfExtent(getXAxis())).toEqual([]);
    });

    it('unzoomed category axis ticks are unchanged', function () {
        chart.setOption({
            animation: false,
            xAxis: { type: 'category', data: ['a', 'b', 'c', 'd'] },
            yAxis: {},
            series: [{ type: 'bar', data: [1, 2, 3, 4] }]
        });
        const axis = getXAxis();
        const extent = axis.getExtent();
        const coords = axis.getTicksCoords().map(function (tick: any) {
            return tick.coord;
        });
        expect(coords.length).toBe(5);
        expect(coords[0]).toBeCloseTo(extent[0], 6);
        expect(coords[coords.length - 1]).toBeCloseTo(extent[1], 6);
        expect(collectOutOfExtent(axis)).toEqual([]);
    });
});

